// Turns the prospect's homepage into plain text and a brand color.
// It never fails: with no website, a blocked request or an empty page,
// it returns website_ok = false and the proposal is written from the call notes.

const res = $input.first().json;
const html = typeof res.data === 'string' ? res.data : '';

if (res.error || html.length < 200) {
  return [{ json: { website_ok: false, website_title: '', website_description: '', website_text: '', site_color: '' } }];
}

const pick = (...patterns) => {
  for (const re of patterns) {
    const m = html.match(re);
    if (m && m[1]) return m[1].trim();
  }
  return '';
};

const decode = (s) => s
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');

const title = decode(pick(/<title[^>]*>([\s\S]*?)<\/title>/i));
const description = decode(pick(
  /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i,
  /<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i,
  /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i,
));

const text = decode(html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
  .replace(/<[^>]+>/g, ' '))
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 6000);

// ----- Brand color -----
// 1st choice: the theme-color meta tag. 2nd: the most repeated saturated color in
// the page's own CSS. Greys, near-white and near-black never count as a brand color.
const toHex6 = (h) => {
  h = String(h || '').trim().toLowerCase();
  if (/^#[0-9a-f]{3}$/.test(h)) return '#' + h.slice(1).split('').map((c) => c + c).join('');
  return /^#[0-9a-f]{6}$/.test(h) ? h : '';
};
const isBrandLike = (h) => {
  const r = parseInt(h.slice(1, 3), 16), g = parseInt(h.slice(3, 5), 16), b = parseInt(h.slice(5, 7), 16);
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  return max - min > 45 && max > 50 && min < 235;
};

let siteColor = toHex6(pick(
  /<meta[^>]+name=["']theme-color["'][^>]+content=["']([^"']*)["']/i,
  /<meta[^>]+content=["']([^"']*)["'][^>]+name=["']theme-color["']/i,
));
if (!siteColor || !isBrandLike(siteColor)) {
  const counts = {};
  for (const m of html.matchAll(/#([0-9a-fA-F]{6}|[0-9a-fA-F]{3})\b/g)) {
    const h = toHex6('#' + m[1]);
    if (h && isBrandLike(h)) counts[h] = (counts[h] || 0) + 1;
  }
  const top = Object.entries(counts).sort((a, b) => b[1] - a[1])[0];
  siteColor = top && top[1] >= 2 ? top[0] : '';
}

return [{
  json: {
    website_ok: text.length > 100,
    website_title: title.slice(0, 200),
    website_description: description.slice(0, 400),
    website_text: text,
    site_color: siteColor,
  },
}];

