const TEMPLATE = "<!doctype html>
<!--
  SALES PROPOSAL TEMPLATE
  -----------------------
  Replacement engine: plain string substitution of {{variable}}.
  Fields ending in _html are filled with HTML fragments built by the
  Build HTML Code node from the arrays in the JSON the LLM generates.

  SIMPLE VARIABLES
    client_company, contact_name, contact_role, date, primary_color,
    secondary_color, proposal_title, proposal_subtitle, diagnosis_summary,
    solution_summary, total_price, price_note, cta_text, agency_name,
    agency_email, agency_phone

  GENERATED BLOCKS (arrays -> HTML)
    diagnosis_points_html   <li>...</li>            from diagnosis_points[]
    solution_blocks_html    <div class="card">...   from solution_blocks[]
    scope_items_html        <li class="deliv">...   from scope_items[]
    pricing_rows_html       <tr>...</tr>            from pricing_rows[]
    timeline_phases_html    <li class="phase">...   from timeline_phases[]
    next_steps_html         <li>...</li>            from next_steps[]
-->
<html lang="en">
<head>
<meta charset="utf-8">
<title>Proposal — {{client_company}}</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Source+Serif+4:wght@500;600;700&display=swap" rel="stylesheet">
<style>
{{theme_css}}
</style>
</head>
