    <span>{{agency_name}}</span>
  </div>
</section>

<!-- ============ 3. PROPOSED SOLUTION ============ -->
<section class="page">
  <div class="sec-head">
    <span class="sec-num">02</span>
    <h2 class="sec-title">Proposed solution</h2>
  </div>
  <p class="lead">{{solution_summary}}</p>
  <div class="cards">
    {{solution_blocks_html}}
  </div>
  <div class="foot">
    <span>Proposal — {{client_company}}</span>
    <span>{{agency_name}}</span>
  </div>
</section>

<!-- ============ 4. SCOPE AND DELIVERABLES ============ -->
<section class="page">
  <div class="sec-head">
    <span class="sec-num">03</span>
    <h2 class="sec-title">Scope and deliverables</h2>
  </div>
  <ul class="delivs">
    {{scope_items_html}}
  </ul>
  <div class="foot">
    <span>Proposal — {{client_company}}</span>
    <span>{{agency_name}}</span>
  </div>
</section>

<!-- ============ 5. INVESTMENT ============ -->
<section class="page">
  <div class="sec-head">
    <span class="sec-num">04</span>
    <h2 class="sec-title">Investment</h2>
  </div>
  <table class="pricing">
    <thead>
