  <div class="total">
    <span class="label">Total</span>
    <span class="value">{{total_price}}</span>
  </div>
  <p class="price-note">{{price_note}}</p>
  <div class="foot">
    <span>Proposal — {{client_company}}</span>
    <span>{{agency_name}}</span>
  </div>
