<!-- ============ 6. TIMELINE ============ -->
<section class="page">
  <div class="sec-head">
    <span class="sec-num">05</span>
    <h2 class="sec-title">Implementation timeline</h2>
  </div>
  <ul class="timeline">
    {{timeline_phases_html}}
  </ul>
  <div class="foot">
    <span>Proposal — {{client_company}}</span>
    <span>{{agency_name}}</span>
  </div>
</section>

<!-- ============ 7. NEXT STEPS ============ -->
<section class="page">
  <div class="sec-head">
    <span class="sec-num">06</span>
