  .pricing thead th{ background: none; color: var(--ink-faint); border-bottom: 1.5px solid var(--ink); padding-left: 0; padding-right: 0; }
  .pricing tbody td{ padding-left: 0; padding-right: 0; }
  .pricing tbody tr:nth-child(even){ background: none; }
  .total{ background: none; border: 0; border-top: 1.5px solid var(--ink); border-radius: 0; padding: 5mm 0; }
  .total .value{ color: var(--ink); }
  .timeline .dur{ background: none; color: var(--ink-faint); padding: 0; }
  .steps li::before{ background: none; color: var(--brand); border: 1.4px solid var(--brand); }
  .cta{ background: var(--panel); color: var(--ink); }
  .cta .contact{ border-top-color: var(--rule); }
",
  "corporate": "  /* ===== Theme: Corporate — formal serif headings, structured tables ===== */
  .cover-band{ height: 10mm; background: var(--brand-2); }
  .cover-title, .sec-title, .card h3, .timeline h3, .findings strong, .delivs strong, .total .value{
    font-family: var(--serif);
    letter-spacing: -0.01em;
  }
  .cover-title{ font-weight: 600; }
  .sec-title{ font-weight: 600; font-size: 18pt; }
  .sec-head{ border-bottom-color: var(--brand-2); }
  .pricing thead th{ background: var(--brand-2); color: var(--on-brand-2); }
  .card{ background: #fff; border-radius: 1mm; border-left: 3px solid var(--brand); }
  .total{ border-radius: 1mm; }
  .cta{ border-radius: 1mm; background: var(--brand-2); color: var(--on-brand-2); }
",
  "bold": "  /* ===== Theme: Bold — full-color cover and strong color blocks ===== */
  .cover{ background: var(--brand); color: var(--on-brand); }
  .cover-band{ display: none; }
  .wordmark, .eyebrow, .cover-title{ color: var(--on-brand); }
  .eyebrow{ opacity: 0.8; }
  .cover-top{ border-bottom-color: color-mix(in srgb, var(--on-brand) 30%, transparent); }
  .cover-top .date, .cover-foot .label{ color: color-mix(in srgb, var(--on-brand) 75%, transparent); }
  .cover-title{ font-size: 38pt; font-weight: 800; letter-spacing: -0.035em; }
  .cover-sub{ color: color-mix(in srgb, var(--on-brand) 88%, transparent); }
  .cover-rule{ background: var(--on-brand); }
  .cover-foot{ border-top-color: color-mix(in srgb, var(--on-brand) 30%, transparent); }
  .cover-foot .muted{ color: color-mix(in srgb, var(--on-brand) 80%, transparent); }
  .sec-head{ border-bottom: 0; background: var(--brand); padding: 4mm 6mm; border-radius: 2mm; }
  .sec-num{ color: var(--on-brand); opacity: 0.75; font-size: 11pt; }
  .sec-title{ color: var(--on-brand); font-weight: 800; }
  .card{ background: var(--brand); border: 0; color: var(--on-brand); }
  .card .num{ color: var(--on-brand); opacity: 0.7; font-size: 16pt; font-weight: 800; }
  .card p{ color: color-mix(in srgb, var(--on-brand) 88%, transparent); }
  .findings li::before{ width: 3.5mm; height: 3.5mm; border-radius: 1mm; }
  .total{ background: var(--brand-2); color: var(--on-brand-2); border: 0; }
  .total .label{ color: color-mix(in srgb, var(--on-brand-2) 80%, transparent); }
  .total .value{ color: var(--on-brand-2); font-weight: 800; font-size: 22pt; }
  .steps li::before{ border-radius: 1.5mm; }
  .cta{ background: var(--brand-2); color: var(--on-brand-2); }
"
};

const form = $('When Proposal Form Submitted').first().json;
const profile = $('Your Business Profile').first().json;
const site = $('Read Prospect Website').first().json;
const ai = $input.first().json.output;

// ===== Design =====
// The form label starts with the theme name ("Minimal — ...").
const choice = String(form['Proposal design'] || '').toLowerCase();
const themeKey = Object.keys(THEMES).find((k) => choice.startsWith(k)) || 'corporate';

// ===== Colors =====
// The prospect's own brand color when their website gives one; otherwise the
// defaults from Your Business Profile. Only a 6-digit hex is accepted, because an
// invalid value silently breaks the CSS of the whole proposal.
const hex = (v) => (typeof v === 'string' && /^#[0-9a-fA-F]{6}$/.test(v.trim()) ? v.trim().toLowerCase() : '');
const channels = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
const darken = (h, amount) =>
  '#' + channels(h).map((c) => Math.round(c * (1 - amount)).toString(16).padStart(2, '0')).join('');
const luminance = (h) => {
  const [r, g, b] = channels(h).map((c) => {
    c /= 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};
const textOn = (h) => (luminance(h) > 0.45 ? '#16161a' : '#ffffff');

let primary = hex(site.site_color);
let secondary = primary ? darken(primary, 0.45) : '';
if (!primary) {
  primary = hex(profile.default_primary_color) || '#1f4fd8';
  secondary = hex(profile.default_secondary_color) || darken(primary, 0.45);
}

const date = DateTime.now().setZone(profile.timezone || 'UTC').setLocale('en').toFormat('LLLL d, yyyy');

// Identity fields come from the form and the profile, never from the AI.
const data = {
  ...ai,
  client_company: form['Company name'],
  contact_name: form['Contact name'],
  contact_role: form['Contact role'] || '',
  date,
  primary_color: primary,
  secondary_color: secondary,
  on_brand: textOn(primary),
  on_brand_2: textOn(secondary),
  agency_name: profile.agency_name,
  agency_email: profile.agency_email,
  agency_phone: profile.agency_phone,
};

// ===== Validation =====
// The template has a fixed page layout: if the counts are off, the PDF comes out
// broken. Better to fail here than spend a PDF API credit.
const n = (k) => (Array.isArray(data[k]) ? data[k].length : 0);
const errors = [];
for (const field of ['client_company', 'contact_name', 'proposal_title', 'proposal_subtitle',
  'diagnosis_summary', 'solution_summary', 'total_price', 'cta_text']) {
  if (!data[field]) errors.push('Missing field "' + field + '".');
}
if (n('solution_blocks') !== 4) errors.push('"solution_blocks" must have exactly 4 (has ' + n('solution_blocks') + ').');
if (n('diagnosis_points') < 3 || n('diagnosis_points') > 5) errors.push('"diagnosis_points" must have 3 to 5 (has ' + n('diagnosis_points') + ').');
if (n('scope_items') < 4 || n('scope_items') > 8) errors.push('"scope_items" must have 4 to 8 (has ' + n('scope_items') + ').');
if (n('pricing_rows') < 1 || n('pricing_rows') > 5) errors.push('"pricing_rows" must have 1 to 5 (has ' + n('pricing_rows') + ').');
if (n('timeline_phases') < 3 || n('timeline_phases') > 6) errors.push('"timeline_phases" must have 3 to 6 (has ' + n('timeline_phases') + ').');
if (n('next_steps') < 3 || n('next_steps') > 5) errors.push('"next_steps" must have 3 to 5 (has ' + n('next_steps') + ').');
if (errors.length) {
  throw new Error('The generated content does not fit the template: ' + errors.join(' | '));
}

// ===== Merge JSON -> HTML =====
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const blocks = {
  diagnosis_points_html: data.diagnosis_points
    .map((p) => '<li><strong>' + esc(p.title) + '</strong><span>' + esc(p.detail) + '</span></li>').join('
'),
  solution_blocks_html: data.solution_blocks
    .map((b, i) => '<div class="card"><span class="num">' + String(i + 1).padStart(2, '0') + '</span>' +
      '<h3>' + esc(b.title) + '</h3><p>' + esc(b.description) + '</p></div>').join('
'),
  scope_items_html: data.scope_items
    .map((a) => '<li class="deliv"><strong>' + esc(a.deliverable) + '</strong><span>' + esc(a.detail) + '</span></li>').join('
'),
  pricing_rows_html: data.pricing_rows
    .map((r) => '<tr><td class="concept"><strong>' + esc(r.item) + '</strong><span>' + esc(r.detail) +
      '</span></td><td class="amount">' + esc(r.amount) + '</td></tr>').join('
'),
  timeline_phases_html: data.timeline_phases
    .map((p) => '<li class="phase"><div class="meta"><h3>' + esc(p.phase) + '</h3><span class="dur">' +
      esc(p.duration) + '</span></div><p>' + esc(p.description) + '</p></li>').join('
'),
  next_steps_html: data.next_steps.map((s) => '<li>' + esc(s) + '</li>').join('
'),
};

const values = { ...data, ...blocks };
const withTheme = TEMPLATE.replace('{{theme_css}}', BASE_CSS + '
' + THEMES[themeKey]);
const html = withTheme.replace(/\{\{(\w+)\}\}/g, (m, key) => {
  if (!(key in values)) return '';
  return key.endsWith('_html') ? values[key] : esc(values[key]);
});

const slug = String(data.client_company || 'client')
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

return [{
  json: {
    company: data.client_company,
    contact: data.contact_name,
    prospect_email: form['Contact email'],
    theme: themeKey,
    colors_from: hex(site.site_color) ? 'prospect website' : 'your business profile',
    agency_name: data.agency_name,
    agency_email: data.agency_email,
    agency_phone: data.agency_phone,
    file_name: 'proposal-' + slug + '.pdf',
    payload: {
      body: html,
      css: '',
      settings: {
        paper_size: 'A4', orientation: '1',
        margin_top: '0', margin_right: '0', margin_bottom: '0', margin_left: '0',
        print_background: '1',
      },
    },
  },
}];

const item = $input.first();
item.binary.data.fileName = $('Build HTML').first().json.file_name;
item.binary.data.fileExtension = 'pdf';
item.binary.data.mimeType = 'application/pdf';
return [item];

